from taf.internal.gnb.oam.rap.client.rap.v2 import FMApi, ApiClient, Configuration

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class FmV1(object):

    def __init__(self, con_details, access_token):
        self.configuration = self._create_configuration_prepare(con_details)
        self.configuration.access_token = access_token
        self.fm_api_instance = FMApi(ApiClient(self.configuration))

    @staticmethod
    def _create_configuration_prepare(con_details):
        config_object = Configuration()
        config_object.host = con_details.make_configuration_host(original_endpoint=config_object.host)
        config_object.retries = 0
        config_object.verify_ssl = con_details.secure
        return config_object

    def get_active_alarms(self):
        return self.fm_api_instance.faults_get(ffault_state="active")

    def get_cleared_alarms(self):
        return self.fm_api_instance.faults_get(ffault_state="cleared")
